#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    ROOTS, NO_HEADER, takesAHeader
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Give every source file a map of itself, and every directory a map of its files.
 *
 *   node scripts/map-the-repo.mjs           # write the maps
 *   node scripts/map-the-repo.mjs --check   # fail if any map is out of date
 *
 * ## What goes in a file header, and what deliberately does not
 *
 * The block carries three things a reader cannot get by looking at the file:
 *
 * - **exports** — what this file offers, without scrolling it;
 * - **used by** — who depends on it, which is invisible from inside the file and is the thing you
 *   actually want before changing anything;
 * - **depends on** — its own imports *within this package*, collapsed to one line.
 *
 * It does NOT restate the import block verbatim. Those lines sit ten rows below, they are already
 * exact, and a generated copy of them is noise that goes stale between generations. `used by` is
 * the direction that earns the space.
 *
 * The hand-written docblock above it is never touched. Prose explaining WHY a file exists is the
 * most valuable thing in this repository and no generator can produce it; this only adds the part
 * that can be derived, and marks itself as derived so nobody edits it by hand.
 *
 * ## Where the maps live
 *
 * - `MAP.md` — the front door: every tree, how big it is, and what is in it.
 * - `<root>/MAP.md` — that tree's directories, plus the files sitting directly in it.
 * - `<root>/<dir>/MAP.md` — one row per file: its purpose line and its exports.
 *
 * All generated. `--check` is wired into `verify`, so a file that moves, an export that is added, or
 * a new dependency all fail the build until the maps are regenerated.
 *
 * The dependency index spans every root at once, which is why `scripts` and `mcp` are mapped
 * alongside `src` rather than left out: the answer to "who reads this data file?" is often an
 * emitter or an MCP tool, and a map of `src` alone would show it with no dependents and imply
 * nothing used it.
 */

import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { pathToFileURL } from 'node:url'

/**
 * The trees that get mapped, and how much of a map each one gets.
 *
 * `headers: false` means the directory gets its `MAP.md` but its files are left alone. `examples`
 * and `templates` exist to be read top-to-bottom and copied into someone else's project; a
 * generated block above the first line is the first thing they would see and the first thing they
 * would have to delete.
 *
 * `site` is a SvelteKit app with its own conventions and is not mapped here.
 */
export const ROOTS = [
  { dir: 'src', headers: true },
  { dir: 'tooling', headers: true },
  { dir: 'scripts', headers: true },
  { dir: 'mcp', headers: true },
  { dir: 'wasm', headers: true },
  { dir: 'examples', headers: false },
  { dir: 'templates', headers: false },
]

const CHECK_ONLY = process.argv.includes('--check')

const BEGIN = ' ── file map ─────────────────────────────────────────────────────────────────'
const END = ' ─────────────────────────────────────────────── generated by `npm run map` ──'

/**
 * Files that get a row in the map but no header of their own.
 *
 * Generated data is enormous, rewritten wholesale by its emitter, and nobody reads the top of it.
 * A header there does not survive: `build` reruns the emitters, the headers vanish, and `--check`
 * goes red on a tree nobody touched — which is precisely how `planner-engine/generated` failed the
 * first full `verify` after this landed. Any `generated/` directory is exempt for that reason, not
 * merely to save churn.
 *
 * They are still MAPPED. The first version skipped them entirely, which dropped
 * `src/data/generated` out of the index altogether: a directory of 40-odd catalogs that the map
 * claimed did not exist. A file you should not edit is exactly the kind you most need the map to
 * name, so it appears in its directory's table with everything else.
 */
export const NO_HEADER = [/\.generated\.ts$/, /[\\/]generated[\\/]/, /specs-generated/]

export const takesAHeader = file => !NO_HEADER.some(pattern => pattern.test(file))

