function walk(dir) {
  return readdirSync(dir).flatMap((entry) => {
    const full = path.join(dir, entry)
    return statSync(full).isDirectory() ? walk(full) : [full]
  })
}

const posix = (file) => file.split(path.sep).join('/')

/**
 * Compare Markdown on its content, not its line endings.
 *
 * Git normalises these files on checkout, so a CRLF working copy would otherwise read as stale on
 * every single run and `--check` would fail forever on a clean tree.
 */
const unixEol = (text) => text.replace(/\r\n/g, '\n')

/**
 * The first sentence of the file's own docblock — its purpose, in its author's words.
 *
 * Two things are deliberately not a purpose: a docblock that turns out to be the first export's
 * TSDoc (that describes one symbol, not the file), and an already-written map block (reading its
 * own output back would make the generator disagree with itself on the second run).
 */
function purposeOf(text) {
  /*
   * Shebang first: every script in `scripts/` opens with one, and leaving it in place made the
   * docblock below it invisible. All 21 read as undocumented, and the count of missing prose on the
   * front page was wrong by that much in the direction that invites pointless work.
   */
  const withoutMap = text
    .replace(/^#![^\n]*\r?\n/, '')
    .replace(new RegExp(`^/\\*${BEGIN}[\\s\\S]*?\\*/(\\r?\\n)?`), '')
  const block = /^\s*\/\*\*([\s\S]*?)\*\//.exec(withoutMap)
  if (!block) return ''
  if (documentsTheNextSymbol(withoutMap.slice(block.index + block[0].length))) return ''

  const lines = block[1]
    .split('\n')
    .map(line => line.replace(/^\s*\*\s?/, '').trim())

  /*
   * The first PARAGRAPH, then the first sentence of it — not the first line.
   *
   * These docblocks wrap at 100 characters, so a first line is usually half a thought. Taking it
   * verbatim produced rows ending "…and how much of it can a", which reads as a corrupted table
   * rather than a summary.
   */
  const start = lines.findIndex(line => line && !line.startsWith('@'))
  if (start === -1) return ''

  const paragraph = lines.slice(start, lines.indexOf('', start) === -1 ? undefined : lines.indexOf('', start))
    .filter(line => !line.startsWith('@'))
    .join(' ')

  const sentence = /^(.*?[.:])(\s|$)/.exec(paragraph)?.[1] ?? paragraph
  return sentence.replace(/\s+/g, ' ').trim()
}

/** Exported names, in the order the file declares them. */
function exportsOf(text) {
  const names = new Set()
  for (const match of text.matchAll(/^export\s+(?:async\s+)?(?:const|function|class|type|interface|enum)\s+([A-Za-z_]\w*)/gm)) {
    names.add(match[1])
  }
  for (const match of text.matchAll(/^export\s*\{([^}]*)\}/gm)) {
    for (const part of match[1].split(',')) {
      const name = part.trim().replace(/^type\s+/, '').split(/\s+as\s+/).pop()?.trim()
      if (name) names.add(name)
    }
  }
  return [...names]
}

/** Imports that resolve inside this package, as repo-relative paths. */
function dependenciesOf(file, text) {
  const here = path.dirname(file)
  const found = new Set()
  for (const match of text.matchAll(/from\s+'(\.[^']*)'/g)) {
    found.add(posix(path.relative('.', path.resolve(here, match[1]))))
  }
  return [...found].sort()
}

function buildIndex(files) {
  const meta = new Map()
  for (const file of files) {
    const text = readFileSync(file, 'utf8')
    meta.set(file, {
      purpose: purposeOf(text),
      exports: exportsOf(text),
      dependsOn: dependenciesOf(file, text),
      text,
    })
  }

  /* Reverse the dependency edges: who imports this file. */
  const usedBy = new Map()
  for (const [file, info] of meta) {
    for (const target of info.dependsOn) {
      const key = target.replace(/\/index$/, '')
      if (!usedBy.has(key)) usedBy.set(key, new Set())
      usedBy.get(key).add(posix(path.relative('.', file)).replace(/\.(ts|mjs)$/, ''))
    }
  }
  return { meta, usedBy }
}

const list = (items, limit) => {
  if (items.length === 0) return '—'
  const shown = items.slice(0, limit).join(', ')
  return items.length > limit ? `${shown} (+${items.length - limit} more)` : shown
}

function headerFor(file, info, usedBy) {
  const key = posix(path.relative('.', file)).replace(/\.(ts|mjs)$/, '')
  const dependents = [...(usedBy.get(key) ?? [])].sort()

  return [
    `/*${BEGIN}`,
    ` * exports    ${list(info.exports, 8)}`,
    ` * depends    ${list(info.dependsOn, 6)}`,
    ` * used by    ${list(dependents, 6)}`,
    ` *${END}`,
    ' */',
  ].join('\n')
}

/**
 * Does the leading docblock belong to the file, or to the first thing in it?
 *
 * Both look identical from the top of the file, and the difference decides where the map block can
 * go. A docblock followed immediately by a declaration is that declaration's TSDoc: inserting
 * between the two detaches it, so the comment stops reaching editor hovers and generated API docs
 * — a silent documentation loss across however many files happen to open that way, with nothing
 * failing to report it.
 *
 * When the next line declares something, the map goes above the docblock instead.
 */
function documentsTheNextSymbol(after) {
  return /^\s*(?:export\s+)?(?:declare\s+)?(?:default\s+)?(?:async\s+)?(?:const|let|var|function|class|interface|type|enum|abstract)\b/
    .test(after)
}

/**
 * Replace an existing block, or insert one after the file's own docblock.
 *
 * Every newline is matched as `\r?\n` and the block is joined with whatever the file already uses.
 * Much of this repository is CRLF, and an `\n`-only match for the end of a docblock fails on those
 * files — so the block landed ABOVE the prose instead of below it, which hid the docblock from the
 * next run's `purposeOf` and made every map lose its Purpose column on the second generation.
 *
 * Running the generator twice and diffing is what caught it. A generator nobody re-runs looks
 * correct forever.
 */
function withHeader(text, header) {
  const eol = text.includes('\r\n') ? '\r\n' : '\n'
  const block = header.split('\n').join(eol)

  const existing = new RegExp(`/\\*${BEGIN}[\\s\\S]*?\\*/(\\r?\\n)?`, '')
  const stripped = text.replace(existing, '')

  const docblock = /^(\s*\/\*\*[\s\S]*?\*\/\r?\n)/.exec(stripped)
  if (docblock && !documentsTheNextSymbol(stripped.slice(docblock[1].length))) {
    return stripped.slice(0, docblock[1].length) + block + eol + stripped.slice(docblock[1].length)
  }
  const shebang = /^(#![^\n]*\r?\n)/.exec(stripped)
  const at = shebang ? shebang[1].length : 0
  return stripped.slice(0, at) + block + eol + stripped.slice(at)
}

function directoryMap(dir, files, meta) {
  const rows = files
    .map((file) => {
      const info = meta.get(file)
      return `| \`${path.basename(file)}\` | ${info.purpose || '—'} | ${list(info.exports, 4)} |`
    })
    .sort()

  return [
    `<!-- Generated by \`npm run map\`. Do not edit. -->`,
    ``,
    `# ${posix(dir)}`,
    ``,
    DIRECTORY_PURPOSE[posix(dir)] ?? '',
    ``,
    `| File | Purpose | Exports |`,
    `|---|---|---|`,
    ...rows,
    ``,
    `[← ${posix(dir).split('/')[0]}](${'../'.repeat(posix(dir).split('/').length - 1)}MAP.md) · [← the package](${'../'.repeat(posix(dir).split('/').length)}MAP.md)`,
    ``,
  ].join('\n')
}

/**
 * One tree's index, at `<root>/MAP.md`.
 *
 * The root is a directory like any other, so its own file table lives here too rather than in a
 * second `MAP.md` alongside — which is what the first version wrote, one on top of the other,
 * leaving `--check` permanently red against a file it had just written itself.
 */
function rootMap(root, byDirectory, meta) {
  const rows = [...byDirectory.entries()]
    .filter(([dir]) => posix(dir) !== root && posix(dir).startsWith(`${root}/`))
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([dir, files]) => {
      const purpose = DIRECTORY_PURPOSE[posix(dir)] ?? ''
      return `| [\`${posix(dir)}\`](${posix(path.relative(root, dir))}/MAP.md) | ${files.length} | ${purpose} |`
    })

  const own = (byDirectory.get(root) ?? []).map((file) => {
    const info = meta.get(file)
    return `| \`${path.basename(file)}\` | ${info.purpose || '—'} | ${list(info.exports, 4)} |`
  }).sort()

  return [
    `<!-- Generated by \`npm run map\`. Do not edit. -->`,
    ``,
    `# ${root}`,
    ``,
    DIRECTORY_PURPOSE[root] ?? '',
    ``,
    ...(rows.length > 0
      ? [`| Directory | Files | What lives here |`, `|---|---|---|`, ...rows, ``]
      : []),
    ...(own.length > 0
      ? [
          rows.length > 0 ? `## Directly in \`${root}\`` : '',
          rows.length > 0 ? `` : '',
          `| File | Purpose | Exports |`,
          `|---|---|---|`,
          ...own,
          ``,
        ].filter((line, index) => !(line === '' && index < 2 && rows.length === 0))
      : []),
    `[← the package](../MAP.md)`,
    ``,
  ].join('\n')
}

/**
 * The front door, at `MAP.md`.
 *
 * One page naming every tree that gets mapped and how big it is. The count of files still missing a
 * purpose sentence lives here too: the generator cannot write those — only a person can — so the
 * honest thing is a number that moves rather than a blank column nobody tallies.
 */
function packageMap(byDirectory, meta) {
  const rows = ROOTS.map(({ dir, headers }) => {
    const count = [...byDirectory.entries()]
      .filter(([d]) => posix(d) === dir || posix(d).startsWith(`${dir}/`))
      .reduce((total, [, files]) => total + files.length, 0)
    return `| [\`${dir}\`](${dir}/MAP.md) | ${count} | ${DIRECTORY_PURPOSE[dir] ?? ''} | ${headers ? 'yes' : 'no'} |`
  })

  const undocumented = [...meta.values()].filter(info => !info.purpose).length

  return [
    `<!-- Generated by \`npm run map\`. Do not edit. -->`,
    ``,
    `# Where everything is`,
    ``,
    `Each tree below has a \`MAP.md\` naming its directories; each directory has one naming its`,
    `files, what each is for, and what each exports. Where **Headers** says yes, every file also`,
    `carries a block listing its exports, what it depends on, and — the part you cannot see from`,
    `inside the file — what depends on it.`,
    ``,
    `| Tree | Files | What lives here | Headers |`,
    `|---|---:|---|---|`,
    ...rows,
    ``,
    `Regenerate with \`npm run map\`. \`npm run lint:map\` runs inside \`verify\` and fails if any of`,
    `it has drifted, so none of these files should ever be edited by hand.`,
    ``,
    `The prose above each generated block is written by hand, and is the one thing no generator can`,
    `produce. ${meta.size - undocumented} of ${meta.size} files have one; ${undocumented} do not, and`,
    `show as \`—\` in their directory's Purpose column.`,
    ``,
  ].join('\n')
}

/**
 * Generate, or check, everything.
 *
 * This is a function rather than top-level code because `takesAHeader` is imported by
 * `the-repo-maps-itself.test.ts` — so the test and the generator cannot disagree about which files
 * are exempt. Without the guard below, that import would regenerate the whole package mid-test and
 * could call `process.exit(1)` from inside the runner.
 */
function main() {
/*
 * One index across every root, so the dependency edges cross them.
 *
 * That is the point of including `scripts` and `mcp` rather than mapping `src` alone: the answer to
 * "who reads this data file?" is often an emitter or an MCP tool, and a map of `src` by itself
 * cannot say so — it would show a data file with no dependents and imply nothing uses it.
 */
const files = ROOTS
  .flatMap(({ dir }) => walk(dir))
  .filter(file => /\.(ts|mjs)$/.test(file))
  .filter(file => !file.includes('.test.'))
  .sort()

const { meta, usedBy } = buildIndex(files)

const headerRoots = new Set(ROOTS.filter(root => root.headers).map(root => root.dir))
const inRootWithHeaders = file => headerRoots.has(posix(file).split('/')[0])

const byDirectory = new Map()
for (const file of files) {
  const dir = path.dirname(file)
  if (!byDirectory.has(dir)) byDirectory.set(dir, [])
  byDirectory.get(dir).push(file)
}

/*
 * A new directory has to be described before it can be mapped.
 *
 * The alternative is the blank cell the first version rendered: a directory in the index with
 * nothing said about it, which is exactly the "where does this live?" question the map exists to
 * answer. One sentence is cheap; seven silent blanks were not noticed until the table was read.
 */
const undescribed = [...byDirectory.keys()].map(posix).filter(dir => !(dir in DIRECTORY_PURPOSE))
if (undescribed.length > 0) {
  console.error(
    `These directories have no entry in DIRECTORY_PURPOSE (scripts/map-the-repo.mjs).\n`
    + `Add one sentence saying what lives in each:\n`,
  )
  for (const dir of undescribed) console.error(`  ${dir}`)
  process.exit(1)
}

const stale = []

for (const file of files) {
  if (!takesAHeader(file) || !inRootWithHeaders(file)) continue
  const info = meta.get(file)
  const next = withHeader(info.text, headerFor(file, info, usedBy))
  if (next === info.text) continue
  if (CHECK_ONLY) stale.push(posix(file))
  else writeFileSync(file, next)
}

const rootDirs = new Set(ROOTS.map(root => root.dir))

/** Write when the content differs; under `--check`, record it and write nothing. */
const emit = (target, next) => {
  const current = (() => {
    try { return readFileSync(target, 'utf8') } catch { return '' }
  })()
  if (unixEol(current) === next) return
  if (CHECK_ONLY) stale.push(posix(target))
  else writeFileSync(target, next)
}

for (const [dir, dirFiles] of byDirectory) {
  /* A root's own `MAP.md` is its index, written below, and carries its file table too. */
  if (rootDirs.has(posix(dir))) continue
  emit(path.join(dir, 'MAP.md'), directoryMap(dir, dirFiles, meta))
}

for (const { dir } of ROOTS) {
  emit(path.join(dir, 'MAP.md'), rootMap(dir, byDirectory, meta))
}

emit('MAP.md', packageMap(byDirectory, meta))

if (CHECK_ONLY && stale.length > 0) {
  console.error(`${stale.length} map(s) are out of date. Run \`npm run map\`:\n`)
  for (const file of stale.slice(0, 20)) console.error(`  ${file}`)
  if (stale.length > 20) console.error(`  … and ${stale.length - 20} more`)
  process.exit(1)
}

console.log(
  CHECK_ONLY
    ? `Maps are current — ${files.length} files, ${byDirectory.size} directories.`
    : `Mapped ${files.length} files across ${byDirectory.size} directories.`,
)
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) main()
